UPDATE companies SET description='Ray''s Western Wear & Saddlery operates from Oacoma, South Dakota, a location it has occupied since 1996 when the business moved to capture Interstate 90 traffic. The company traces its roots to April 1957, when Ray Steckelberg purchased a men''s clothing store in nearby Chamberlain and began selling horse tack from the basement. The Steckelberg family has retained ownership across four generations; today the store is led by great‑granddaughter Brooke and her husband Kaiden, continuing a legacy that spans more than 65 years.

The store functions as a full‑line western retailer, stocking a wide assortment of boots, denim, seasonal apparel, and equestrian tack. Its sales floor emphasizes boot variety — marketed as the largest selection in the state — and includes a dedicated tack room where saddle and horse‑fitting services are offered.

The business serves the western lifestyle market, supplying both work‑oriented gear and fashion‑forward seasonal collections.

The company positions itself as "South Dakota''s Cowboy Store," highlighting its family heritage, personalized fitting expertise, and a product mix built on fit, stretch, and durability. The transition from a basement tack operation to a destination retail outlet reflects a deliberate focus on serving the region''s horse and ranch culture.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Western wear retail", "Boot fitting and sales", "Saddle and tack fitting", "Equestrian equipment sales", "Seasonal apparel retail"], "industries": ["Western wear retail", "Equestrian equipment retail", "Footwear retail", "Apparel retail"], "materials": ["Leather", "Denim"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family\u2011owned since 1957, now in its fourth generation", "Largest boot selection in South Dakota", "Saddle and horse\u2011tack fitting services offered on site", "Located on I\u201190 to serve travelers with horse trailers"], "facts_used": ["Founded April 1957 by Ray Steckelberg -> /about-us", "Family-owned, now fourth generation Brooke and Kaiden -> /about-us", "Moved to Oacoma on I\u201190 in August 1996 -> /about-us", "Largest boot selection in South Dakota -> /", "Saddle and horse tack fitting services (We Fit The Horse Too!) -> /", "Carries Ariat and SoGlo brands -> /", "Denim described with exceptional fit, built-in stretch, dependable durability -> /", "Family owned for 65+ years -> /about-us", "Headquarters Oacoma, South Dakota -> db"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "SHOP BOOTS", "founded_year": "1957", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='ray-s-western-wear-saddlery' AND approved AND profile IS NULL;
UPDATE companies SET description='Founded in 1990 in Meridian, Idaho, Ready Made Plastic Trays operates as a licensed and certified thermoform plastic tray manufacturer serving businesses and the public. The company has built its reputation on American-made trays for packaging and storage applications.

The company manufactures high-precision trays using High Impact Polystyrene (HIPS), offering food-grade, medical-grade, and anti-static variants in stock configurations with round, square, or rectangular pockets. An in-house CNC tooling shop supports custom fixture design up to two inches deep, enabling tailored solutions for complex component shapes. Both stock and custom orders are fulfilled with domestic and international shipping.

Customers span aerospace, automotive, dental, electronics, firearms, food and beverage, machining, manufacturing, medical, optical, medical devices, and mechanical sectors. The firm highlights long-term relationships with clients in medical device shipping and aerospace component protection.

Ready Made emphasizes domestically sourced materials traceable to original manufacturers, ISO 9001:2015 certification, and a no-nonsense ordering process with volume discounts. The company attributes its longevity to rapid production turnaround and a commitment to personal service, with customers noting consistent delivery since 2009.', certifications=ARRAY['ISO 9001:2015']::text[], profile='{"capabilities": ["Thermoforming", "CNC machining", "Custom tooling design", "Stock tray fulfillment", "Custom tray manufacturing", "Domestic shipping", "International shipping", "Volume discount pricing", "Free sample provision", "Custom color matching"], "industries": ["Aerospace", "Automotive", "Dental", "Electronics", "Firearms", "Food & Beverage", "Machining", "Manufacturing", "Medical", "Optical", "Medical Devices", "Mechanical"], "materials": ["High Impact Polystyrene (HIPS)", "Food-grade HIPS", "Medical-grade HIPS", "Anti-static HIPS"], "equipment": ["CNC tooling shop"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["ISO 9001:2015 certified quality management", "Domestically sourced materials traceable to original manufacturers", "In-house CNC tooling shop for custom fixtures up to 2 inches deep", "Rapid production and no-nonsense ordering with volume discounts", "American-made trays since 1990 with real-person customer support"], "facts_used": ["Founded in 1990 -> /about-us", "Headquarters in Meridian, Idaho -> db", "ISO 9001:2015 certified -> /", "Manufactures thermoformed plastic trays -> /about-us", "Uses High Impact Polystyrene (HIPS) -> /about-us", "Offers food-grade, medical-grade, anti-static models -> /", "Custom trays up to 2 inches deep via CNC tooling shop -> / and /about-us", "Industries served: aerospace, automotive, dental, electronics, firearms, food & beverage, machining, manufacturing, medical, optical -> /", "Also serves medical devices, mechanical sectors -> /about-us", "Domestically sourced materials traceable to original manufacturer